iff-narrow"}, {"observation": "Leaf bases are rendered as widely spaced cylindrical pegs with rounded caps, not a dense diamond lattice of flat-faced wedge stubs.", "evidence_ids": ["render-2", "render-3", "reference-1", "reference-2"], "impact": "blocker", "uncertain": false, "causal_hypothesis": null, "trait_id": "trunk-leaf-base-diamond-pattern"}, {"observation": "There is no fibrous matting between the stubs; the trunk is a smooth grained cylinder.", "evidence_ids": ["render-3", "reference-1", "reference-2"], "impact": "blocker", "uncertain": false, "causal_hypothesis": null, "trait_id": "trunk-fibrous-matting"}, {"observation": "Each render shows a single unbranched stem of near-constant diameter.", "evidence_ids": ["render-0", "render-1", "render-2", "reference-0", "reference-1"], "impact": "supported", "uncertain": false, "causal_hypothesis": null, "trait_id": "solitary-columnar-stem"}, {"observation": "The trunk is straight and of near-constant diameter with no waviness, and nothing grows on it other than the leaf-base pegs.", "evidence_ids": ["render-0", "render-1", "reference-1"], "impact": "supported", "uncertain": false, "causal_hypothesis": null, "trait_id": null}, {"observation": "In the whole views the fronds read near-black, dark green, not blue-green or grey-green. The closer trunk view of the same geometry shows grey-green leaflets mixed with black ones.", "evidence_ids": ["render-0", "render-1", "render-2", "reference-1"], "impact": "blocker", "uncertain": true, "causal_hypothesis": "Possibly backlit or backface shading of the leaflets rather than the base material colour; not established.", "trait_id": "frond-colour-range"}, {"observation": "A collar of collapsed fronds hangs against the upper trunk below the living crown and partly hides it. In render-2 it is grey, but it looks like a smooth flat sheet rather than individual dead fronds.", "evidence_ids": ["render-0", "render-1", "render-2", "reference-0"], "impact": "optional", "uncertain": fal